2. xvfb also claims a unique 'impossible' layout and can be detected. (`Backslash='\'` claims US ANSI, while `IntlBackslash='<'` claims European ISO hardware) https://bugs.freedesktop.org/show_bug.cgi?id=29938


```js
await (async () => {
  if (!navigator.keyboard?.getLayoutMap)
    return { detected: 'unknown', expected: null };
  const map = await navigator.keyboard.getLayoutMap();
  const g = c => map.has(c) ? map.get(c) : undefined;
  const sig = {
    Backslash: g('Backslash'), 
    IntlBackslash: g('IntlBackslash'),
    KeyQ: g('KeyQ'),
    KeyY: g('KeyY'),
  };

  const fingerprints = {
    'us-ansi':   ['\\', undefined, 'q', 'y'],
    'us-iso':    ['\\', '\\',      'q', 'y'],
    'uk':        ['#',  '\\',      'q', 'y'],
    'de':        ['#',  '<',       'q', 'z'],
    'fr':        ['*',  '<',       'a', 'y'],
    'dvorak':    ['\\', undefined, "'", 'f'],
    'colemak':   ['\\', undefined, 'q', 'j'],
    'xvfb':      ['\\', '<',       'q', 'y'],
  };
  const key = [sig.Backslash, sig.IntlBackslash, sig.KeyQ, sig.KeyY];
  const detected = Object.entries(fingerprints)
    .find(([, f]) => f.every((v, i) => v === key[i]))?.[0] ?? 'unknown';

  const tz = (Intl.DateTimeFormat().resolvedOptions().timeZone || '').toLowerCase();
  const expected =
    tz === 'europe/london'   ? 'uk' :
    tz.startsWith('america/')? 'us-ansi' :
    tz === 'europe/berlin'   ? 'de' :
    tz === 'europe/paris'    ? 'fr' : null;
    // ... add more for other countries

  return { expected, detected, signature: sig };
})();
```

The spoofed `MAX_VERTEX_UNIFORM_VECTORS` (4095) doesn't match the real driver limit (1024 on Mesa). A detection script can just compile a shader using the claimed number of uniforms — if it fails, the value is spoofed.

Quick binary search finds the real limit in ~12 iterations:

```js
(() => {
  const gl = document.createElement('canvas').getContext('webgl2');
  const claimed = gl.getParameter(gl.MAX_VERTEX_UNIFORM_VECTORS);
  let lo = 1, hi = claimed;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    const s = gl.createShader(gl.VERTEX_SHADER);
    gl.shaderSource(s, `#version 300 es\nuniform vec4 u[${mid}];\nvoid main(){gl_Position=u[0];}`);
    gl.compileShader(s);
    gl.getShaderParameter(s, gl.COMPILE_STATUS) ? lo = mid : hi = mid - 1;
    gl.deleteShader(s);
  }
  return { claimed, real: lo, spoofed: lo < claimed };
})()
// { claimed: 4095, real: 1024, spoofed: true }
```

